void enetc_msg_handle_rxmsg ( struct enetc_pf * pf , int vf_id , u16 * status ) { struct enetc_msg_swbd * msg = & pf -> rxmsg [ vf_id ] ; struct device * dev = & pf -> si -> pdev -> dev ; struct enetc_msg_cmd_header * cmd_hdr ; u16 cmd_type ; * status = ENETC_MSG_CMD_STATUS_OK ; cmd_hdr = ( enetc_msg_cmd_header * ) msg -> vaddr ; cmd_type = cmd_hdr -> type ; switch ( cmd_type ) { case ENETC_MSG_CMD_MNG_MAC : break ; default : dev_err ( dev , "command not supported (cmd_type: 0x%x)\n" , cmd_type ) ; } } 